from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f'anchor not found: {path}: {old[:80]!r}')
    if text.count(old) != 1:
        raise SystemExit(f'anchor not unique: {path}: {old[:80]!r}')
    p.write_text(text.replace(old, new, 1))


def append_once(path: str, marker: str, block: str) -> None:
    p = Path(path)
    text = p.read_text()
    if marker in text:
        return
    p.write_text(text.rstrip() + '\n\n' + block.strip() + '\n')


