append_once(
    pool_tests,
    'def test_explicit_release_is_idempotent_and_reuses_capacity',
    '''def test_explicit_release_is_idempotent_and_reuses_capacity(db_session):\n    node = add_node(db_session)\n    transport = FakeCredentialTransport()\n    service = PoolAssignmentService(db_session, transport)\n    prepared = service.prepare(request("a"))\n    service.confirm(\n        PoolReservationConfirmRequest(\n            assignment_id=prepared.assignment_id,\n            confirmation_token=prepared.confirmation_token,\n        )\n    )\n\n    released = service.release(\n        PoolReservationReleaseRequest(\n            assignment_id=prepared.assignment_id,\n            subject_key="a" * 64,\n        )\n    )\n    replay = service.release(\n        PoolReservationReleaseRequest(\n            assignment_id=prepared.assignment_id,\n            subject_key="a" * 64,\n        )\n    )\n\n    assert released.status == "revoked" == replay.status\n    assert transport.removed.count(prepared.assignment_id) == 1\n    assert db_session.get(VpnNode, node.id).current_clients == 0\n\n    replacement = service.prepare(request("b"))\n    assert replacement.client_port == prepared.client_port\n    assert db_session.get(VpnNode, node.id).current_clients == 1\n\n\ndef test_explicit_release_refuses_stale_owner(db_session):\n    node = add_node(db_session)\n    transport = FakeCredentialTransport()\n    service = PoolAssignmentService(db_session, transport)\n    prepared = service.prepare(request("a"))\n    service.confirm(\n        PoolReservationConfirmRequest(\n            assignment_id=prepared.assignment_id,\n            confirmation_token=prepared.confirmation_token,\n        )\n    )\n\n    with pytest.raises(HTTPException) as error:\n        service.release(\n            PoolReservationReleaseRequest(\n                assignment_id=prepared.assignment_id,\n                subject_key="b" * 64,\n            )\n        )\n\n    assert error.value.status_code == 409\n    assert error.value.detail == "assignment_owner_changed"\n    assert db_session.get(VpnAssignment, prepared.assignment_id).status == "active"\n    assert db_session.get(VpnNode, node.id).current_clients == 1\n    assert transport.removed == []\n\n\ndef test_failed_explicit_release_is_retryable_without_losing_capacity(db_session):\n    node = add_node(db_session)\n    transport = FakeCredentialTransport(remove_ok=False)\n    service = PoolAssignmentService(db_session, transport)\n    prepared = service.prepare(request("a"))\n    service.confirm(\n        PoolReservationConfirmRequest(\n            assignment_id=prepared.assignment_id,\n            confirmation_token=prepared.confirmation_token,\n        )\n    )\n    payload = PoolReservationReleaseRequest(\n        assignment_id=prepared.assignment_id,\n        subject_key="a" * 64,\n    )\n\n    with pytest.raises(HTTPException) as error:\n        service.release(payload)\n\n    assert error.value.status_code == 503\n    assert error.value.detail == "assignment_release_failed"\n    assert db_session.get(VpnAssignment, prepared.assignment_id).status == "revocation_pending"\n    assert db_session.get(VpnNode, node.id).current_clients == 1\n\n    transport.remove_ok = True\n    retried = service.release(payload)\n    assert retried.status == "revoked"\n    assert db_session.get(VpnNode, node.id).current_clients == 0\n''',
)

